INSERT INTO "public"."nl2sql_request_log" VALUES (3, '6b4f8303-2e51-4a29-b3a5-a2487afd0651', '查询工单关联的编码规则组、标签组和包装规则', 'SELECT 
  wo.wo_no AS 工单号,
  wo.wo_status AS 工单状态,
  p.part_no AS 料号,
  p.part_name AS 品名,
  erg.group_name AS 编码规则组名称,
  er.rule_name AS 编码规则名称,
  llg.group_name AS 标签组名称,
  ll.label_name AS 标签名称,
  pr.rule_name AS 包装规则名称,
  prd.container_name AS 包装容器,
  prd.container_level AS 包装层级,
  prd.container_capacity AS 包装容量
FROM t_pd_wo wo
LEFT JOIN t_bd_part p ON wo.part_id = p.id
LEFT JOIN t_bc_encode_rule_group_detail ergd ON p.id = ergd.bind_id
LEFT JOIN t_bc_encode_rule_group erg ON ergd.group_id = erg.id
LEFT JOIN t_bc_encode_rule er ON ergd.encode_rule_id = er.id
LEFT JOIN t_lb_label_group llg ON erg.id = llg.group_id
LEFT JOIN t_lb_label ll ON llg.id = ll.group_id
LEFT JOIN t_packing_rule pr ON erg.id = pr.id
LEFT JOIN t_packing_rule_detail prd ON pr.id = prd.rule_id
WHERE wo.wo_no IS NOT NULL
LIMIT 500;', 'SELECT 
  wo.wo_no AS 工单号,
  wo.wo_status AS 工单状态,
  p.part_no AS 料号,
  p.part_name AS 品名,
  erg.group_name AS 编码规则组名称,
  er.rule_name AS 编码规则名称,
  llg.group_name AS 标签组名称,
  ll.label_name AS 标签名称,
  pr.rule_name AS 包装规则名称,
  prd.container_name AS 包装容器,
  prd.container_level AS 包装层级,
  prd.container_capacity AS 包装容量
FROM t_pd_wo wo
LEFT JOIN t_bd_part p ON wo.part_id = p.id
LEFT JOIN t_bc_encode_rule_group_detail ergd ON p.id = ergd.bind_id
LEFT JOIN t_bc_encode_rule_group erg ON ergd.group_id = erg.id
LEFT JOIN t_bc_encode_rule er ON ergd.encode_rule_id = er.id
LEFT JOIN t_lb_label_group llg ON erg.id = llg.id
LEFT JOIN t_lb_label ll ON llg.id = ll.label_group_id
LEFT JOIN t_packing_rule pr ON erg.id = pr.id
LEFT JOIN t_packing_rule_detail prd ON pr.id = prd.rule_id
WHERE wo.wo_no IS NOT NULL
